# Simpler - just find all connected components of non-background colors
grid = [[int(x) for x in line.split()] for line in input_grid_str.strip().split('\n')]

from collections import deque

visited = [[False]*27 for _ in range(27)]
regions = []

for r in range(27):
    for c in range(27):
        val = grid[r][c]
        if val not in [0, 5]:
            if not visited[r][c]:
                region = []
                queue = deque([(r, c)])
                visited[r][c] = True
                while queue:
                    rr, cc = queue.popleft()
                    region.append((rr, cc))
                    val_here = grid[rr][cc]
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = rr+dr, cc+dc
                        if 0 <= nr < 27 and 0 <= nc < 27:
                            if not visited[nr][nc] and grid[nr][nc] == val_here:
                                visited[nr][nc] = True
                                queue.append((nr, nc))
                regions.append({'value': val, 'cells': region, 'size': len(region)})

print(f"Found {len(regions)} regions")
for reg in regions:
    print(f"Value {reg['value']}, size {reg['size']}, header {reg['cells'][0]}")

